/// Texte der Oberfläche, je Schlüssel des Katalogs ein Zugriff.
public enum L {
    public enum Account {
        /// Signed in. With “Automatic”, the Midea account takes over when Wi-Fi does not work. {storage}
        public static func footerSignedIn(storage: String) -> String { Localizer.text("account.footerSignedIn", ["storage": storage]) }
        /// Optional. {storage}
        public static func footerSignedOut(storage: String) -> String { Localizer.text("account.footerSignedOut", ["storage": storage]) }
        /// Midea account and password removed.
        public static var removed: String { Localizer.text("account.removed") }
        /// Signed in and saved.
        public static var signedIn: String { Localizer.text("account.signedIn") }
    }
    public enum App {
        /// Restart now
        public static var restartNow: String { Localizer.text("app.restartNow") }
        public enum Window {
            /// Klimacontrol
            public static var main: String { Localizer.text("app.window.main") }
            /// Mini window
            public static var mini: String { Localizer.text("app.window.mini") }
        }
    }
    public enum Appearance {
